  "interpretation[object<Interpretation>]": {
    "revised_instruction[string]": "RETROACTIVE PARENT JOB: Reconstruct and govern the already-started IssueStack JSON Issue-comment input-surface implementation and comprehensive test-suite project. The implementation and multiple tests were performed before an Issue #1→#2→#3 parent job existed. Create this versioned job record now, preserve verified completed work and actual run receipts in its mapped scratchpad, and continue the remaining semantic coverage, test-suite optimization and recovery verification from that same job. Exclude Issue #8 from the requested full per-Issue semantic test suite; do not misstate the existing optional Issue #8 route gap as resolved. Do not imply the project is complete.",
    "user_intent[object<UserIntent>]": {
      "goal[string]": "Retroactively anchor the existing IssueStack comment-input implementation and comprehensive nonduplicative test-suite work in one correctly linked parent job and scratchpad.",
      "expected_outcome[string]": "Verified Issue #2 parent job with an automatically mapped Issue #3 scratchpad containing historical implementation/test evidence, the elaborated constrained covering-array and minimum set-cover solver specification, and a truthful remaining-work ledger.",
      "requested_abstraction_level[string]": "Executable workflow/test implementation with formal mathematical optimization and independently verified durable evidence.",
      "requested_action_scope[string]": "Register the already ongoing work as a retrospective job, document all verified past work and unresolved tests, preserve history, and continue remaining coverage/recovery tasks without marking success prematurely."
    }
  },
  "requirements[array<Requirement>]": [
    {
      "id[string]": "R1",
      "description[string]": "Define and implement the JSON Issue-comment input surface as a workspace-isolated, versioned contract with authorization, target ownership checks, exact create/edit/prepend/replace/append semantics, receipt and readback verification.",
      "acceptance_criteria[array<AcceptanceCriterion>]": [
        {
          "text[string]": "Schema, runtime, and entry GitHub Actions workflow are committed on main and independently readable; execution/error outcomes are validated."
        }
      ]
    },
    {
      "id[string]": "R2",
      "description[string]": "Integrate the input surface with secondary Issue workflows for Issues #1, #2, #5, #7, #13 and #30 through validated virtual issue_comment contexts, preserving native triggers.",
      "acceptance_criteria[array<AcceptanceCriterion>]": [
        {
          "text[string]": "Correct event/action/Issue routing is verified for all six targeted Issues; Issue #8 integration is explicitly out of scope for this job's comprehensive test-suite requirement."
        }
      ]
    },
    {
      "id[string]": "R3",
      "description[string]": "Run and preserve actual live input-surface integration evidence for representative eligible Issue/action routes; distinguish downstream semantic outcomes and failures.",
      "acceptance_criteria[array<AcceptanceCriterion>]": [
        {
          "text[string]": "Record actual GitHub Actions run IDs, writer readbacks, secondary job status, failure/correction history, and retained test comments; do not extrapolate from smoke cases."
        }
      ]
    },
    {
      "id[string]": "R4",
      "description[string]": "Build a comprehensive isolated test suite for valid and invalid entries per Issue, with paired semantic fixtures, negative routing, state-machine transition assertions, receipts, idempotency, authorization and error-recovery guarantees.",
      "acceptance_criteria[array<AcceptanceCriterion>]": [
        {
          "text[string]": "Each distinct feasible semantic equivalence class and state transition for Issues #1, #2, #5, #7, #13 and #30 has executable assertions and observed outcomes; do not claim full coverage from writer-level mocks alone."
        }
      ]
    },
    {
      "id[string]": "R5",
      "description[string]": "Optimize the test suite by modeling coverage obligations, constrained candidates, finite-state transitions and weighted minimum set cover; preserve the expanded mathematical solver proposal in this job's Issue #3 scratchpad.",
      "acceptance_criteria[array<AcceptanceCriterion>]": [
        {
          "text[string]": "Specify exact incidence matrix, feasible test constraints, objective, proof limits, greedy baseline, and HiGHS/OR-Tools options, with a requirement-to-test coverage certificate design."
        }
      ]
    },
    {
      "id[string]": "R6",
      "description[string]": "Resolve or explicitly document concurrent input ordering, pending-receipt recovery, failed mutations, and workflow interruption without false success claims.",
      "acceptance_criteria[array<AcceptanceCriterion>]": [
        {
          "text[string]": "Replay, race and crash invariants have executable tests and reproducible evidence; unresolved real-GitHub concurrency remains explicitly unverified."
        }
      ]
    },
    {
      "id[string]": "R7",
      "description[string]": "Record retrospective inventory of already completed implementation and tests, preserve exact evidence and outstanding requirements, and maintain repository file metadata for substantive source changes.",
      "acceptance_criteria[array<AcceptanceCriterion>]": [
        {
          "text[string]": "Permanent Issue #2 job and Issue #3 scratchpad map correctly, include historical commits, CI result and route-test evidence, and distinguish completed from pending work."
        }
      ]
    }
  ],
